let big = Vec3(10, 10, 10);
print("a < big       =", a < big);          // true
print("big >= a      =", big >= a);         // true
assertEq(a < big, true);
assertEq(big > a, true);
assertEq(a <= Vec3(1, 2, 3), true);

// --- bitwise operators (per-operator traps) ---
